        D2s2_Dt2 = d2s2_dt2 + ds2_dQ * d2Q_dt2 + d2s2_dQ2 * dQ_dt * dQ_dt - ds2_dr * rtt + d2s2_dr2 * rt * rt + T(2.0) * d2s2_dtQ * dQ_dt - T(2.0) * d2s2_dtr * rt
        ds2_dt = Ds2_Dt
        ds2_dr = Ds2_Dr
        ds2_dph = Ds2_Dph
        d2s2_dph2 = D2s2_Dph2
        d2s2_dr2 = D2s2_Dr2
        d2s2_dtph = D2s2_Dtph
        d2s2_dt2 = D2s2_Dt2
        sqrts2 = sqrt(s2)
        s2_15 = s2 * sqrts2
        s2_25 = s2 * s2_15
        s2_35 = s2 * s2_25
        s2_45 = s2 * s2_35
        s2_55 = s2 * s2_45
        phi_s = A / s2_35
        dPhiS_dt = (-7 * ds2_dt * A + 2 * dA_dt * s2) / (T(2.0) * s2_45)
        dPhiS_dr = (-7 * ds2_dr * A + 2 * dA_dr * s2) / (T(2.0) * s2_45)
        dPhiS_dth = (-7 * ds2_dth * A + 2 * dA_dth * s2) / (T(2.0) * s2_45)
        dPhiS_dph = (-7 * ds2_dph * A + 2 * dA_dph * s2) / (T(2.0) * s2_45)
        d2PhiS_dr2 = (63 * ds2_dr * ds2_dr * A - 14 * s2 * (2 * dA_dr * ds2_dr + d2s2_dr2 * A) + 4 * d2A_dr2 * s2 * s2) / (T(4.0) * s2_55)
        d2PhiS_dth2 = (63 * ds2_dth * ds2_dth * A - 14 * s2 * (2 * dA_dth * ds2_dth + d2s2_dth2 * A) + 4 * d2A_dth2 * s2 * s2) / (T(4.0) * s2_55)
        d2PhiS_dph2 = (63 * ds2_dph * ds2_dph * A - 14 * s2 * (2 * dA_dph * ds2_dph + d2s2_dph2 * A) + 4 * d2A_dph2 * s2 * s2) / (T(4.0) * s2_55)
        d2PhiS_dt2 = (63 * ds2_dt * ds2_dt * A - 14 * s2 * (2 * dA_dt * ds2_dt + d2s2_dt2 * A) + 4 * d2A_dt2 * s2 * s2) / (T(4.0) * s2_55)
        d2PhiS_dtph = (63 * ds2_dph * ds2_dt * A - 14 * s2 * (dA_dt * ds2_dph + dA_dph * ds2_dt + d2s2_dtph * A) + 4 * d2A_dtph * s2 * s2) / (T(4.0) * s2_55)
        d2PhiS_dtr = T(NaN)
        d2PhiS_dtth = T(NaN)
        d2PhiS_drth = T(NaN)
        d2PhiS_drph = T(NaN)
        d2PhiS_dthph = T(NaN)
        sinth = sin(theta)
        sinth2 = sinth * sinth
        sin2th = sin(2 * theta)
        cos2th = cos(2 * theta)
        r2 = r * r
        r3 = r2 * r
        r4 = r2 * r2
        a2 = a * a
        a4 = a2 * a2
        src_out = -((2 * a2 * dPhiS_dr - a2 * d2PhiS_dph2 - a4 * d2PhiS_dr2 - a2 * d2PhiS_dth2 - 4 * dPhiS_dr * r - 2 * a2 * dPhiS_dr * r +
            4 * d2PhiS_dph2 * r + 2 * a * d2PhiS_dtph * r + 4 * a2 * d2PhiS_dr2 * r + 2 * d2PhiS_dth2 * r + 6 * dPhiS_dr * r2 - 2 * d2PhiS_dph2 * r2 - 4 * d2PhiS_dr2 * r2 -
            2 * a2 * d2PhiS_dr2 * r2 - d2PhiS_dth2 * r2 - 2 * dPhiS_dr * r3 + 4 * d2PhiS_dr2 * r3 - d2PhiS_dr2 * r4 +
            (a4 * d2PhiS_dt2 + 4 * a * d2PhiS_dtph * r + 2 * d2PhiS_dt2 * r4 + a2 * d2PhiS_dt2 * r * (2 + 3 * r)) * sinth2 +
            cos2th * (a4 * d2PhiS_dr2 - 2 * a * d2PhiS_dtph * r + (-2 + r) * r * (d2PhiS_dth2 + 2 * dPhiS_dr * (-1 + r) + d2PhiS_dr2 * (-2 + r) * r) +
                      a2 * (-d2PhiS_dph2 + d2PhiS_dth2 + 2 * dPhiS_dr * (-1 + r) - 4 * d2PhiS_dr2 * r + 2 * d2PhiS_dr2 * r2) +
                      a2 * d2PhiS_dt2 * (a2 + (-2 + r) * r) * sinth2) -
            a2 * dPhiS_dth * sin2th + 2 * dPhiS_dth * r * sin2th -
            dPhiS_dth * r2 * sin2th)) /
         ((sinth2 * (a2 + (-2 + r) * r) * (a2 + 2 * r2 + a2 * cos2th)))
        dPhiS_dx[0] = dPhiS_dt
        dPhiS_dx[1] = dPhiS_dr
        dPhiS_dx[2] = dPhiS_dth
        dPhiS_dx[3] = dPhiS_dph
        PhiS_out = phi_s
        d2PhiS_dx2[0] = d2PhiS_dt2
        d2PhiS_dx2[1] = d2PhiS_dtr
        d2PhiS_dx2[2] = d2PhiS_dtth
        d2PhiS_dx2[3] = d2PhiS_dtph
        d2PhiS_dx2[4] = d2PhiS_dr2
        d2PhiS_dx2[5] = d2PhiS_drth
        d2PhiS_dx2[6] = d2PhiS_drph
        d2PhiS_dx2[7] = d2PhiS_dth2
        d2PhiS_dx2[8] = d2PhiS_dthph
        d2PhiS_dx2[9] = d2PhiS_dph2
    return (PhiS_out,
            SVector{4,T}(dPhiS_dx[0], dPhiS_dx[1], dPhiS_dx[2], dPhiS_dx[3]),
            SVector{10,T}(d2PhiS_dx2[0], d2PhiS_dx2[1], d2PhiS_dx2[2], d2PhiS_dx2[3],
                          d2PhiS_dx2[4], d2PhiS_dx2[5], d2PhiS_dx2[6], d2PhiS_dx2[7],
                          d2PhiS_dx2[8], d2PhiS_dx2[9]),
            src_out)
end

"""m-mode singular field (complex), including the phase exp(-i m phi_p)."""
function phis_m(ctx::EquatorialCtx{T}, m::Integer, x::Coordinate{T}) where {T}
    PhiS = _ovec(T, 2)
        M = ctx.M
        a = ctx.a
        xp = ctx.xp
        A0060 = ctx.A0060
        A0061 = ctx.A0061
        A0080 = ctx.A0080
        A0081 = ctx.A0081
        A0240 = ctx.A0240
        A0241 = ctx.A0241
        A0260 = ctx.A0260
        A0261 = ctx.A0261
        A0420 = ctx.A0420
        A0421 = ctx.A0421
        A0440 = ctx.A0440
        A0441 = ctx.A0441
        A0600 = ctx.A0600
        A0601 = ctx.A0601
        A0620 = ctx.A0620
        A0621 = ctx.A0621
        A0800 = ctx.A0800
        A0801 = ctx.A0801
        A1060 = ctx.A1060
        A1061 = ctx.A1061
        A1080 = ctx.A1080
        A1240 = ctx.A1240
        A1241 = ctx.A1241
        A1260 = ctx.A1260
        A1420 = ctx.A1420
        A1421 = ctx.A1421
        A1440 = ctx.A1440
        A1600 = ctx.A1600
        A1601 = ctx.A1601
        A1620 = ctx.A1620
        A1800 = ctx.A1800
        A2040 = ctx.A2040
        A2041 = ctx.A2041
        A2060 = ctx.A2060
        A2061 = ctx.A2061
        A2220 = ctx.A2220
        A2221 = ctx.A2221
        A2240 = ctx.A2240
        A2241 = ctx.A2241
        A2400 = ctx.A2400
        A2401 = ctx.A2401
        A2420 = ctx.A2420
        A2421 = ctx.A2421
        A2600 = ctx.A2600
        A2601 = ctx.A2601
        A3040 = ctx.A3040
        A3041 = ctx.A3041
        A3060 = ctx.A3060
        A3220 = ctx.A3220
        A3221 = ctx.A3221
        A3240 = ctx.A3240
        A3400 = ctx.A3400
        A3401 = ctx.A3401
        A3420 = ctx.A3420
        A3600 = ctx.A3600
        A4020 = ctx.A4020
        A4021 = ctx.A4021
        A4040 = ctx.A4040
        A4041 = ctx.A4041
        A4200 = ctx.A4200
        A4201 = ctx.A4201
        A4220 = ctx.A4220
        A4221 = ctx.A4221
        A4400 = ctx.A4400
        A4401 = ctx.A4401
        A5020 = ctx.A5020
        A5021 = ctx.A5021
        A5040 = ctx.A5040
        A5200 = ctx.A5200
        A5201 = ctx.A5201
        A5220 = ctx.A5220
        A5400 = ctx.A5400
        A6000 = ctx.A6000
        A6001 = ctx.A6001
        A6020 = ctx.A6020
        A6021 = ctx.A6021
        A6200 = ctx.A6200
        A6201 = ctx.A6201
        A7000 = ctx.A7000
        A7001 = ctx.A7001
        A7020 = ctx.A7020
        A7200 = ctx.A7200
        A8000 = ctx.A8000
        A8001 = ctx.A8001
        A9000 = ctx.A9000
        alpha20 = ctx.alpha20
        alpha02 = ctx.alpha02
        beta = ctx.beta
        c = ctx.c
        ReA = _ovec(T, 5)
        ImA = _ovec(T, 5)
        r = x.r
        theta = x.theta
        rp = xp.r
        thetap = xp.theta
        dr = r - rp
        dtheta = theta - thetap
        dr2 = dr * dr
        dr4 = dr2 * dr2
        dr6 = dr4 * dr2
        dr8 = dr4 * dr4
        dtheta2 = dtheta * dtheta
        dtheta4 = dtheta2 * dtheta2
        dtheta8 = dtheta4 * dtheta4
        ReA[0] = (A6000 + A7000 * dr) * dr6 + (A8000 + A9000 * dr) * dr8 + (A4200 + dr * (A5200 + dr * (A6200 + A7200 * dr))) * dr4 * dtheta2 + ((A2400 + A3400 * dr) * dr2 + (A4400 + A5400 * dr) * dr4 + (A0600 + dr * (A1600 + dr * (A2600 + A3600 * dr))) * dtheta2) * dtheta4 + (A0800 + A1800 * dr) * dtheta8
        ImA[0] = (A6001 + A7001 * dr) * dr6 + A8001 * dr8 + (A4201 + dr * (A5201 + A6201 * dr)) * dr4 * dtheta2 + ((A2401 + A3401 * dr) * dr2 + A4401 * dr4 + (A0601 + dr * (A1601 + A2601 * dr)) * dtheta2) * dtheta4 + A0801 * dtheta8
        ReA[1] = (A4020 + dr * (A5020 + dr * (A6020 + A7020 * dr))) * dr4 + (A2220 + dr * (A3220 + dr * (A4220 + A5220 * dr))) * dr2 * dtheta2 + (A0420 + A1420 * dr + (A2420 + A3420 * dr) * dr2 + (A0620 + A1620 * dr) * dtheta2) * dtheta4
        ImA[1] = (A4021 + dr * (A5021 + A6021 * dr)) * dr4 + (A2221 + dr * (A3221 + A4221 * dr)) * dr2 * dtheta2 + (A0421 + A1421 * dr + A2421 * dr2 + A0621 * dtheta2) * dtheta4
        ReA[2] = (A2040 + A3040 * dr) * dr2 + (A4040 + A5040 * dr) * dr4 + (A0240 + dr * (A1240 + dr * (A2240 + A3240 * dr))) * dtheta2 + (A0440 + A1440 * dr) * dtheta4
        ImA[2] = (A2041 + A3041 * dr) * dr2 + A4041 * dr4 + (A0241 + dr * (A1241 + A2241 * dr)) * dtheta2 + A0441 * dtheta4
        ReA[3] = A0060 + A1060 * dr + (A2060 + A3060 * dr) * dr2 + (A0260 + A1260 * dr) * dtheta2
        ImA[3] = A0061 + A1061 * dr + A2061 * dr2 + A0261 * dtheta2
        ReA[4] = A0080 + A1080 * dr
        ImA[4] = A0081
        alpha = alpha20 * dr2 + alpha02 * dtheta2
        C1 = alpha / beta
        C = _ovec(T, 27)
        C[0] = 1
        C[1] = C1
        C[2] = C[1] * C[1]
        C[3] = C[2] * C[1]
        C[4] = C[2] * C[2]
        C[5] = C[3] * C[2]
        C[6] = C[3] * C[3]
        C[7] = C[4] * C[3]
        C[8] = C[4] * C[4]
        C[9] = C[5] * C[4]
        C[10] = C[5] * C[5]
        C[11] = C[6] * C[5]
        C[12] = C[6] * C[6]
        C[13] = C[7] * C[6]
        C[14] = C[7] * C[7]
        C[15] = C[8] * C[7]
        C[16] = C[8] * C[8]
        C[17] = C[9] * C[8]
        C[18] = C[9] * C[9]
        C[19] = C[10] * C[9]
        C[20] = C[10] * C[10]
        C[21] = C[11] * C[10]
        C[22] = C[11] * C[11]
        C[23] = C[12] * C[11]
        C[24] = C[12] * C[12]
        C[25] = C[13] * C[12]
        C[26] = C[13] * C[13]
        (ellK, ellE) = _ellKE(ctx, C1)
        ellip = _ovec0(T[ellK, ellE])
        if m < 0 || m > 20
            error("effsource: requested m-mode is not supported (need 0 <= m <= 20)")
        end
        num_re = 0
        num_im = 0
        for i in 0:(2)-1
            for j in 0:(5)-1
                for k in max(j - i, 0):(m + 2 + j)
                    num_re += reei(T,m,i,j,k) * ellip[i] * ReA[j] * C[k]
                end
                for k in max(j - i - 1, 0):(m + 1 + j)
                    num_im += imei(T,m,i,j,k) * ellip[i] * ImA[j] * C[k]
                end
            end
        end
        alpha_plus_beta_10 = alpha + beta
        alpha_plus_beta_05 = sqrt(alpha_plus_beta_10)
        alpha_plus_beta_15 = alpha_plus_beta_10 * alpha_plus_beta_05
        alpha_plus_beta_25 = alpha_plus_beta_10 * alpha_plus_beta_15
        PhiSb_re = T(4.0) * num_re / (beta * C[3] * alpha_plus_beta_25)
        PhiSb_im = -T(32.0) * num_im / (beta * beta * C[2] * alpha_plus_beta_15)
        sincmdr = sin(c * m * dr)
        coscmdr = cos(c * m * dr)
        RePhiS = PhiSb_re * coscmdr + PhiSb_im * sincmdr
        ImPhiS = PhiSb_im * coscmdr - PhiSb_re * sincmdr
        cosmph = cos(m * xp.phi)
        sinmph = sin(m * xp.phi)
        PhiS[0] = RePhiS * cosmph + ImPhiS * sinmph
        PhiS[1] = ImPhiS * cosmph - RePhiS * sinmph
    return Complex(PhiS[0], PhiS[1])
end

