        alpha_plus_beta_25 = alpha_plus_beta_10 * alpha_plus_beta_15
        PhiSb_re = T(4.0) * num_re / (beta * C[3] * alpha_plus_beta_25)
        PhiSb_im = -T(32.0) * num_im / (beta * beta * C[2] * alpha_plus_beta_15)
        sincmdr = sin(c * m * dr)
        coscmdr = cos(c * m * dr)
        RePhiS = PhiSb_re * coscmdr + PhiSb_im * sincmdr
        ImPhiS = PhiSb_im * coscmdr - PhiSb_re * sincmdr
        cosmph = cos(m * xp.phi)
        sinmph = sin(m * xp.phi)
        PhiS[0] = RePhiS * cosmph + ImPhiS * sinmph
        PhiS[1] = ImPhiS * cosmph - RePhiS * sinmph
    return Complex(PhiS[0], PhiS[1])
end

